type legacyOrder struct {
    OrderID string `json:"order_id"`
    SKU     string `json:"sku"`
    Qty     int    `json:"qty"`
}

func toCanonical(l legacyOrder) (Order, error) {
    if l.OrderID == "" || l.Qty <= 0 {
        return Order{}, ErrInvalidMessage // route to the invalid-message path
    }
    return Order{ID: l.OrderID, SKU: strings.ToUpper(l.SKU), Qty: l.Qty}, nil
}
